import (
	"sync"

	"benchmark.local/iam/internal/domain"
)

// OrganizationRepository is a concurrency-safe in-memory organization store.
type OrganizationRepository struct {
	mu            sync.RWMutex
	organizations map[domain.OrganizationID]domain.Organization
}

func NewOrganizationRepository() *OrganizationRepository {
	return &OrganizationRepository{organizations: make(map[domain.OrganizationID]domain.Organization)}
}

// Create stores an organization. OwnerID is mandatory because every
// organization must have an owner.
func (r *OrganizationRepository) Create(organization domain.Organization) error {
	if organization.ID == "" || organization.OwnerID == "" {
		return domain.NewInvalid("organization must have an owner")
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.organizations[organization.ID]; exists {
		return domain.NewConflict("organization already exists")
	}
	r.organizations[organization.ID] = organization
	return nil
}

func (r *OrganizationRepository) GetByID(id domain.OrganizationID) (domain.Organization, error) {
	r.mu.RLock()
	organization, exists := r.organizations[id]
	r.mu.RUnlock()
	if !exists {
		return domain.Organization{}, domain.NewNotFound("organization not found")
	}
	return organization, nil
}

func (r *OrganizationRepository) Update(organization domain.Organization) error {
	if organization.ID == "" || organization.OwnerID == "" {
		return domain.NewInvalid("organization must have an owner")
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.organizations[organization.ID]; !exists {
		return domain.NewNotFound("organization not found")
	}
	r.organizations[organization.ID] = organization
	return nil
}

func (r *OrganizationRepository) Delete(id domain.OrganizationID) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.organizations[id]; !exists {
		return domain.NewNotFound("organization not found")
	}
	delete(r.organizations, id)
	return nil
}

func (r *OrganizationRepository) List() []domain.Organization {
	r.mu.RLock()
	result := make([]domain.Organization, 0, len(r.organizations))
	for _, organization := range r.organizations {
		result = append(result, organization)
	}
	r.mu.RUnlock()
	return result
}
package repository

import (
	"sync"
	"time"

	"benchmark.local/iam/internal/domain"
)

type membershipKey struct {
	organizationID domain.OrganizationID
	userID         domain.UserID
}

// MembershipRepository is a concurrency-safe in-memory store. The composite
// index makes (organization,user) uniqueness atomic with insertion.
type MembershipRepository struct {
	mu                 sync.RWMutex
	memberships        map[domain.ID]domain.Membership
	byOrganizationUser map[membershipKey]domain.ID
}

func NewMembershipRepository() *MembershipRepository {
	return &MembershipRepository{
		memberships:        make(map[domain.ID]domain.Membership),
		byOrganizationUser: make(map[membershipKey]domain.ID),
	}
}

func (r *MembershipRepository) Create(membership domain.Membership) error {
	if membership.ID == "" || membership.OrganizationID == "" || membership.UserID == "" {
		return domain.NewInvalid("invalid membership")
	}
	key := membershipKey{organizationID: membership.OrganizationID, userID: membership.UserID}
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, exists := r.memberships[membership.ID]; exists {
		return domain.NewConflict("membership already exists")
	}
	if _, exists := r.byOrganizationUser[key]; exists {
		return domain.NewConflict("membership already exists")
	}
	r.memberships[membership.ID] = membership
	r.byOrganizationUser[key] = membership.ID
	return nil
}

func (r *MembershipRepository) GetByID(id domain.ID) (domain.Membership, error) {
	r.mu.RLock()
	membership, exists := r.memberships[id]
	r.mu.RUnlock()
	if !exists {
		return domain.Membership{}, domain.NewNotFound("membership not found")
	}
	return membership, nil
}

func (r *MembershipRepository) Get(organizationID domain.OrganizationID, userID domain.UserID) (domain.Membership, error) {
	key := membershipKey{organizationID: organizationID, userID: userID}
	r.mu.RLock()
	id, exists := r.byOrganizationUser[key]
	membership := r.memberships[id]
	r.mu.RUnlock()
	if !exists {
		return domain.Membership{}, domain.NewNotFound("membership not found")
	}
	return membership, nil
}

func (r *MembershipRepository) Update(membership domain.Membership) error {
	if membership.ID == "" || membership.OrganizationID == "" || membership.UserID == "" {
		return domain.NewInvalid("invalid membership")
	}
	r.mu.Lock()
	defer r.mu.Unlock()
	old, exists := r.memberships[membership.ID]
	if !exists {
		return domain.NewNotFound("membership not found")
	}
	key := membershipKey{organizationID: membership.OrganizationID, userID: membership.UserID}
	if otherID, used := r.byOrganizationUser[key]; used && otherID != membership.ID {
		return domain.NewConflict("membership already exists")
	}
	oldKey := membershipKey{organizationID: old.OrganizationID, userID: old.UserID}
	if oldKey != key {
		delete(r.byOrganizationUser, oldKey)
		r.byOrganizationUser[key] = membership.ID
	}
	r.memberships[membership.ID] = membership
	return nil
}

// UpdateRole changes a member's built-in role while preserving the invariant
// that an organization always has an owner.
func (r *MembershipRepository) UpdateRole(organizationID domain.OrganizationID, userID domain.UserID, role string, now time.Time) (domain.Membership, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	key := membershipKey{organizationID: organizationID, userID: userID}
	id, exists := r.byOrganizationUser[key]
	if !exists {
		return domain.Membership{}, domain.NewNotFound("membership not found")
	}
	membership := r.memberships[id]
	if membership.Role == "owner" && role != "owner" && r.ownerCountLocked(organizationID) == 1 {
		return domain.Membership{}, domain.NewConflict("organization must have an owner")
	}
	membership.Role = role
	membership.UpdatedAt = now
	r.memberships[id] = membership
	return membership, nil
}

// RemoveRole replaces an assignment with the default viewer role. The
// assignment check and last-owner guard happen under the same lock so a
// concurrent role change cannot bypass the organization invariant.
func (r *MembershipRepository) RemoveRole(organizationID domain.OrganizationID, userID domain.UserID, role string, now time.Time) (domain.Membership, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	key := membershipKey{organizationID: organizationID, userID: userID}
	id, exists := r.byOrganizationUser[key]
	if !exists {
		return domain.Membership{}, domain.NewNotFound("membership not found")
	}
	membership := r.memberships[id]
	if membership.Role != role {
		return domain.Membership{}, domain.NewNotFound("role assignment not found")
	}
	if role == "owner" && r.ownerCountLocked(organizationID) == 1 {
		return domain.Membership{}, domain.NewConflict("organization must have an owner")
	}
	membership.Role = "viewer"
	membership.UpdatedAt = now
	r.memberships[id] = membership
	return membership, nil
}

// DeleteMember removes a member, refusing to remove an owner before transfer.
func (r *MembershipRepository) DeleteMember(organizationID domain.OrganizationID, userID domain.UserID) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	key := membershipKey{organizationID: organizationID, userID: userID}
	id, exists := r.byOrganizationUser[key]
	if !exists {
		return domain.NewNotFound("membership not found")
	}
	if r.memberships[id].Role == "owner" {
		return domain.NewConflict("ownership must be transferred first")
	}
	delete(r.memberships, id)
	delete(r.byOrganizationUser, key)
	return nil
}

// TransferOwnership changes both membership roles under one repository lock.
// The caller updates the organization's denormalized OwnerID while holding
// the same application-level organization lock.
func (r *MembershipRepository) TransferOwnership(organizationID domain.OrganizationID, currentOwnerID, newOwnerID domain.UserID, now time.Time) (domain.Membership, domain.Membership, error) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if currentOwnerID == newOwnerID {
		return domain.Membership{}, domain.Membership{}, domain.NewConflict("new owner must be different")
	}
	oldID, exists := r.byOrganizationUser[membershipKey{organizationID: organizationID, userID: currentOwnerID}]
	if !exists || r.memberships[oldID].Role != "owner" {
		return domain.Membership{}, domain.Membership{}, domain.NewConflict("current owner required")
	}
	newID, exists := r.byOrganizationUser[membershipKey{organizationID: organizationID, userID: newOwnerID}]
	if !exists {
		return domain.Membership{}, domain.Membership{}, domain.NewNotFound("membership not found")
	}
	old := r.memberships[oldID]
	newOwner := r.memberships[newID]
	old.Role = "admin"
	old.UpdatedAt = now
	newOwner.Role = "owner"
	newOwner.UpdatedAt = now
	r.memberships[oldID] = old
	r.memberships[newID] = newOwner
	return old, newOwner, nil
}

func (r *MembershipRepository) ownerCountLocked(organizationID domain.OrganizationID) int {
	count := 0
	for _, membership := range r.memberships {
		if membership.OrganizationID == organizationID && membership.Role == "owner" {
			count++
		}
	}
	return count
}

func (r *MembershipRepository) Delete(id domain.ID) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	membership, exists := r.memberships[id]
	if !exists {
		return domain.NewNotFound("membership not found")
	}
	delete(r.memberships, id)
	delete(r.byOrganizationUser, membershipKey{organizationID: membership.OrganizationID, userID: membership.UserID})
	return nil
}

func (r *MembershipRepository) ListByOrganization(organizationID domain.OrganizationID) []domain.Membership {
	r.mu.RLock()
	result := make([]domain.Membership, 0)
	for _, membership := range r.memberships {
		if membership.OrganizationID == organizationID {
			result = append(result, membership)
		}
	}
	r.mu.RUnlock()
	return result
}

func (r *MembershipRepository) ListByUser(userID domain.UserID) []domain.Membership {
	r.mu.RLock()
	result := make([]domain.Membership, 0)
	for _, membership := range r.memberships {
		if membership.UserID == userID {
			result = append(result, membership)
		}
	}
	r.mu.RUnlock()
	return result
}
package repository

import (
	"crypto/subtle"
	"encoding/hex"
	"sort"
	"sync"
	"time"

	"benchmark.local/iam/internal/domain"
)

type APIKeyRepository struct {
	mu     sync.RWMutex
	keys   map[domain.APIKeyID]domain.APIKey
	byHash map[string]domain.APIKeyID
}

func NewAPIKeyRepository() *APIKeyRepository {
	return &APIKeyRepository{keys: make(map[domain.APIKeyID]domain.APIKey), byHash: make(map[string]domain.APIKeyID)}
}

func (r *APIKeyRepository) Create(key domain.APIKey) error {
	if key.ID == "" || key.OrganizationID == "" || key.CreatedBy == "" || key.Name == "" || len(key.Hash) != 32 || len(key.Scopes) == 0 {
		return domain.NewInvalid("invalid api key")
	}
	seen := make(map[domain.Permission]bool)
	for _, scope := range key.Scopes {
		if !domain.ValidPermission(scope) || seen[scope] {
			return domain.NewInvalid("invalid api key scope")
		}
		seen[scope] = true
	}
	hash := hex.EncodeToString(key.Hash)
	r.mu.Lock()
	defer r.mu.Unlock()
	if _, ok := r.keys[key.ID]; ok || r.byHash[hash] != "" {
		return domain.NewConflict("api key already exists")
	}
	key.Hash = append([]byte(nil), key.Hash...)
	key.Scopes = append([]domain.Permission(nil), key.Scopes...)
	r.keys[key.ID] = key
	r.byHash[hash] = key.ID
	return nil
}

func cloneAPIKey(key domain.APIKey) domain.APIKey {
	key.Hash = append([]byte(nil), key.Hash...)
	key.Scopes = append([]domain.Permission(nil), key.Scopes...)
	return key
}

func (r *APIKeyRepository) GetByKey(hash []byte) (domain.APIKey, error) {
	r.mu.RLock()
	id := r.byHash[hex.EncodeToString(hash)]
	key, ok := r.keys[id]
	r.mu.RUnlock()
	if !ok || subtle.ConstantTimeCompare(key.Hash, hash) != 1 || key.RevokedAt != nil {
		return domain.APIKey{}, domain.NewNotFound("api key not found")
	}
	return cloneAPIKey(key), nil
}

func (r *APIKeyRepository) ListByOrganization(orgID domain.OrganizationID) []domain.APIKey {
	r.mu.RLock()
	result := make([]domain.APIKey, 0)
	for _, key := range r.keys {
		if key.OrganizationID == orgID {
			result = append(result, cloneAPIKey(key))
		}
	}
	r.mu.RUnlock()
	sort.Slice(result, func(i, j int) bool { return result[i].CreatedAt.Before(result[j].CreatedAt) })
	return result
}

func (r *APIKeyRepository) Revoke(orgID domain.OrganizationID, id domain.APIKeyID, now time.Time) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	key, ok := r.keys[id]
	if !ok || key.OrganizationID != orgID {
		return domain.NewNotFound("api key not found")
	}
	if key.RevokedAt != nil {
		return domain.NewConflict("api key already revoked")
	}
	key.RevokedAt = &now
	r.keys[id] = key
	return nil
}

// Package domain contains shared IAM domain primitives.
package domain

import (
	"crypto/rand"
	"encoding/hex"
	"errors"
	"fmt"
)

// ID is the common representation of an entity identifier. Values are UUID
// version 4 strings, generated with crypto/rand.
type ID string

type UserID ID
type OrganizationID ID
type SessionID ID
type InviteID ID
type RoleID ID
type APIKeyID ID
type TokenFamilyID ID

// NewID returns a new random UUID version 4 identifier.
func NewID() (ID, error) {
	var value [16]byte
	if _, err := rand.Read(value[:]); err != nil {
		return "", fmt.Errorf("generate id: %w", err)
	}
	value[6] = (value[6] & 0x0f) | 0x40
	value[8] = (value[8] & 0x3f) | 0x80
	encoded := make([]byte, 36)
	hex.Encode(encoded[0:8], value[0:4])
	hex.Encode(encoded[9:13], value[4:6])
	hex.Encode(encoded[14:18], value[6:8])
	hex.Encode(encoded[19:23], value[8:10])
	hex.Encode(encoded[24:36], value[10:16])
	encoded[8], encoded[13], encoded[18], encoded[23] = '-', '-', '-', '-'
	return ID(encoded), nil
}

func newTypedID[T ~string](newValue func() (ID, error)) (T, error) {
	id, err := newValue()
	return T(id), err
}

func NewUserID() (UserID, error) { return newTypedID[UserID](NewID) }

func NewOrganizationID() (OrganizationID, error) { return newTypedID[OrganizationID](NewID) }

func NewSessionID() (SessionID, error) { return newTypedID[SessionID](NewID) }

func NewInviteID() (InviteID, error) { return newTypedID[InviteID](NewID) }

func NewRoleID() (RoleID, error) { return newTypedID[RoleID](NewID) }

func NewAPIKeyID() (APIKeyID, error) { return newTypedID[APIKeyID](NewID) }

func NewTokenFamilyID() (TokenFamilyID, error) { return newTypedID[TokenFamilyID](NewID) }

// ParseID validates the textual UUID representation before converting it to ID.
func ParseID(value string) (ID, error) {
	if len(value) != 36 || value[8] != '-' || value[13] != '-' || value[18] != '-' || value[23] != '-' {
		return "", errors.New("invalid id")
	}
	var raw [16]byte
	if _, err := hex.Decode(raw[:4], []byte(value[0:8])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[4:6], []byte(value[9:13])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[6:8], []byte(value[14:18])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[8:10], []byte(value[19:23])); err != nil {
		return "", errors.New("invalid id")
	}
	if _, err := hex.Decode(raw[10:16], []byte(value[24:36])); err != nil {
		return "", errors.New("invalid id")
	}
	return ID(value), nil
}
